import urllib.request,json,time
symbols={'S&P 500':'%5EGSPC','Nasdaq':'%5EIXIC','Dow':'%5EDJI','WTI crude':'CL%3DF','10Y yield':'%5ETNX','VIX':'%5EVIX'}
for name,sym in symbols.items():
    url=f'https://query1.finance.yahoo.com/v8/finance/chart/{sym}?range=2d&interval=1d'
    try:
        data=json.load(urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=10))
        r=data['chart']['result'][0]
        meta=r['meta']
        price=meta.get('regularMarketPrice')
        prev=meta.get('chartPreviousClose') or meta.get('previousClose')
        pct=(price-prev)/prev*100 if price and prev else None
        print(f'{name}: {price} prev {prev} pct {pct:.2f}%' if pct is not None else f'{name}: {price}')
    except Exception as e:
        print(name,'ERROR',e)
